svg.script:
function boot() {
  var MODE = 'embedded';
  var CATALOG = [{"slug": "n-gon", "name": "n-gon", "bytes": 256233}, {"slug": "2048", "name": "2048", "bytes": 9568}, {"slug": "1", "name": "Threes (1)", "bytes": 6501}];
  var root = document.getElementById('root');
  var grid = document.getElementById('grid');
  var search = document.getElementById('search');
  var player = document.getElementById('player');
  var frame = document.getElementById('frame');
  var busy = document.getElementById('busy');
  var err = document.getElementById('err');
  var barTitle = document.getElementById('bar-title');
  var barSub = document.getElementById('bar-sub');
  var btnBack = document.getElementById('btn-back');
  var btnDl = document.getElementById('btn-dl');
  var btnOpen = document.getElementById('btn-open');
  var btnFs = document.getElementById('btn-fs');
  var baseInput = document.getElementById('base-url');
  var fb = document.getElementById('fallback-note');
  var countEl = document.getElementById('count');

  if (fb) fb.style.display = 'none';

  /* ---------- settings (remote mode) ---------- */
  var store = { get: function (k) { try { return localStorage.getItem(k); } catch (e) { return null; } },
                set: function (k, v) { try { localStorage.setItem(k, v); } catch (e) {} } };
  var settings = {
    base: store.get('truffled.base') || '',
    tpl: store.get('truffled.tpl') || '{base}/games/{slug}/'
  };
  function remoteUrl(slug) {
    var b = (settings.base || '').replace(/\/+$/, '');
    return settings.tpl.replace('{base}', b).replace('{slug}', slug);
  }
  if (baseInput) {
    baseInput.value = settings.base;
    var apply = document.getElementById('base-apply');
    if (apply) apply.addEventListener('click', function () {
      settings.base = baseInput.value.trim();
      store.set('truffled.base', settings.base);
      validate();
    });
    baseInput.addEventListener('keydown', function (e) { if (e.key === 'Enter') apply.click(); });
  }
  function validate() {
    var n = document.getElementById('src-state');
    if (!n) return;
    n.textContent = settings.base ? '' : 'no source set — games cannot load yet';
  }
  validate();

  /* ---------- catalog / cards ---------- */
  function cardBySlug(s) {
    var cards = grid.querySelectorAll('.card');
    for (var i = 0; i < cards.length; i++) if (cards[i].getAttribute('data-slug') === s) return cards[i];
    return null;
  }
  function filter(q) {
    q = (q || '').toLowerCase().trim();
    var cards = grid.querySelectorAll('.card'), shown = 0;
    for (var i = 0; i < cards.length; i++) {
      var hit = !q || cards[i].getAttribute('data-name').toLowerCase().indexOf(q) > -1;
      cards[i].style.display = hit ? '' : 'none';
      if (hit) shown++;
    }
    if (countEl) countEl.textContent = shown + ' / ' + cards.length + ' titles';
  }
  if (search) search.addEventListener('input', function () { filter(search.value); });
  filter('');

  /* ---------- base64 / gzip ---------- */
  function b64bytes(b64) {
    var bin = atob(b64.replace(/[\s\r\n]+/g, ''));
    var u = new Uint8Array(bin.length);
    for (var i = 0; i < bin.length; i++) u[i] = bin.charCodeAt(i);
    return u;
  }
  var cache = {}, activeUrl = null, activeHtml = null, activeSlug = null;

  function fail(msg) {
    busy.classList.remove('on');
    err.textContent = msg;
    err.classList.add('on');
  }

  function inflate(slug) {
    if (cache[slug]) return Promise.resolve(cache[slug]);
    var el = document.getElementById('p-' + slug);
    if (!el) return Promise.reject(new Error('no payload for ' + slug));
    busy.textContent = 'inflating ' + slug + '…';
    busy.classList.add('on'); err.classList.remove('on');
    if (!window.DecompressionStream) {
      return Promise.reject(new Error('nostream'));
    }
    var bytes = b64bytes(el.textContent);
    var stream = new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'));
    return new Response(stream).text().then(function (html) {
      cache[slug] = html;
      return html;
    });
  }

  function open_remote(slug) {
    if (!settings.base) {
      fail('No source set.\n\nType the URL where you host the Truffled source (the folder that contains games/) into the box at the top and press Apply.');
      return;
    }
    var url = remoteUrl(slug);
    busy.textContent = 'loading ' + url;
    busy.classList.add('on'); err.classList.remove('on');
    frame.removeAttribute('srcdoc');
    frame.src = url;
  }

  function play(slug) {
    var card = cardBySlug(slug);
    activeSlug = slug;
    activeHtml = null;
    if (activeUrl) { try { URL.revokeObjectURL(activeUrl); } catch (e) {} activeUrl = null; }
    var name = card ? card.getAttribute('data-name') : slug;
    var kind = card ? (card.getAttribute('data-kind') || '') : '';
    barTitle.textContent = name;
    barSub.textContent = MODE === 'embedded' ? 'offline · gzip payload' : kind;
    root.classList.add('playing');
    if (MODE === 'embedded') {
      btnDl.classList.remove('hide'); btnOpen.classList.add('hide');
      err.classList.remove('on');
      inflate(slug).then(function (html) {
        activeHtml = html;
        activeUrl = URL.createObjectURL(new Blob([html], { type: 'text/html' }));
        frame.removeAttribute('srcdoc');
        frame.src = activeUrl;
        setTimeout(function () { busy.classList.remove('on'); }, 450);
      }).catch(function (e) {
        if (String(e.message) === 'nostream') {
          fail('This browser has no DecompressionStream, so the gzip payload cannot be inflated.\n\nUse Chrome/Edge 80+, Firefox 113+ or Safari 16.4+.');
        } else {
          fail('Could not start: ' + e.message);
        }
      });
    } else {
      btnDl.classList.add('hide'); btnOpen.classList.remove('hide');
      open_remote(slug);
    }
  }

  function back() {
    root.classList.remove('playing');
    err.classList.remove('on'); busy.classList.remove('on');
    frame.src = 'about:blank';
    if (activeUrl) { try { URL.revokeObjectURL(activeUrl); } catch (e) {} activeUrl = null; }
    activeSlug = null;
  }

  grid.addEventListener('click', function (e) {
    var n = e.target;
    while (n && n !== grid && !(n.getAttribute && n.getAttribute('data-slug'))) n = n.parentNode;
    if (n && n.getAttribute && n.getAttribute('data-slug')) play(n.getAttribute('data-slug'));
  });

  btnBack.addEventListener('click', back);
  btnFs.addEventListener('click', function () {
    var w = frame.closest ? (frame.closest('.frame-wrap') || frame) : frame;
    if (document.fullscreenElement) document.exitFullscreen();
    else if (w.requestFullscreen) w.requestFullscreen();
  });
  frame.addEventListener('load', function () { busy.classList.remove('on'); });
  btnOpen.addEventListener('click', function () {
    if (activeSlug) window.open(remoteUrl(activeSlug), '_blank');
  });
  btnDl.addEventListener('click', function () {
    if (!activeHtml) return;
    var blob = new Blob([activeHtml], { type: 'text/html' });
    var a = document.createElementNS('http://www.w3.org/1999/xhtml', 'a');
    a.href = URL.createObjectURL(blob);
    a.download = activeSlug + '.html';
    root.appendChild(a);
    a.click();
    setTimeout(function () { URL.revokeObjectURL(a.href); a.remove(); }, 4000);
  });
  document.addEventListener('keydown', function (e) {
    if (e.key === 'Escape' && root.classList.contains('playing')) back();
  });
  window.addEventListener('message', function (e) {
    if (e.data === 'truffled:back') back();
  });
}
if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', boot);
else boot();
